// ISHGA TUSHISH
NestFactory.create(AppModule)   // modullar, provayderlar, controller'lar yaratiladi (konstruktorlar ishlaydi)
app.init()  yoki  app.listen()  // ↓
    onModuleInit()              // har bir modulning bog'liqliklari tayyor bo'lgach
    onApplicationBootstrap()    // hamma modul tayyor, lekin server hali port tinglamaydi
    (listen() bo'lsa)           // server port tinglay boshlaydi, so'rov qabul qiladi

// ... ilova ishlayapti ...

// TO'XTASH (app.close() yoki SIGTERM / SIGINT signali)
    onModuleDestroy()
    beforeApplicationShutdown(signal)
                                // server ulanishlarni yopadi
    onApplicationShutdown(signal)

import { Injectable, OnModuleInit, OnModuleDestroy } from "@nestjs/common"

@Injectable()
export class DatabaseService implements OnModuleInit, OnModuleDestroy {
    async onModuleInit() {
        await this.connect()      // ilova ishga tushayotganda
    }

    async onModuleDestroy() {
        await this.disconnect()   // ilova to'xtayotganda
    }
}

@Injectable()
export class CurrencyService implements OnModuleInit {
    private rates: Record<string, number> = {}

    async onModuleInit() {
        const res = await fetch("https://example.uz/rates")   // Nest shu yerda kutadi
        this.rates = await res.json()
    }
}

// providers: [UsersService, DbService, CacheService, ConfigService]
//
// ConfigService               daraja 1  ┐ bir vaqtda (parallel)
// CacheService                daraja 1  ┘
// DbService(Config)           daraja 2  ← Config tugagach boshlanadi
// UsersService(Db, Cache)     daraja 3  ← Db va Cache tugagach boshlanadi

// main.ts
const app = await NestFactory.create(AppModule)
app.enableShutdownHooks()                  // SIGTERM, SIGINT va boshqa signallar uchun
