import { Injectable, Module, OnModuleDestroy, OnModuleInit } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

@Injectable()
class HeartbeatService implements OnModuleInit, OnModuleDestroy {
    private timer?: NodeJS.Timeout
    beats = 0
    onModuleInit() {
        this.timer = setInterval(() => this.beats++, 10)
    }
    onModuleDestroy() {
