    }
}

@Module({ providers: [HeartbeatService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const heartbeat = app.get(HeartbeatService)
    while (heartbeat.beats < 2) await new Promise(r => setTimeout(r, 5))
    console.log("kamida 2 ta urish bor:", heartbeat.beats >= 2)
    await app.close()
    const after = heartbeat.beats
    await new Promise(r => setTimeout(r, 40))
    console.log("close()'dan keyin urishlar to'xtadi:", heartbeat.beats === after)
}
main()

