import { BeforeApplicationShutdown, CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, OnApplicationShutdown, OnModuleDestroy, UseInterceptors } from "@nestjs/common"
import { finalize } from "rxjs"

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms))

@Injectable()
class InFlight implements OnModuleDestroy, BeforeApplicationShutdown, OnApplicationShutdown {
    private active = 0
    private idle?: () => void
    enter() { this.active++ }
    leave() { if (--this.active === 0) this.idle?.() }
    onModuleDestroy() { console.log(`1) yopilish boshlandi, faol so'rovlar: ${this.active}`) }
    async beforeApplicationShutdown() {
        if (this.active > 0) await new Promise<void>(resolve => (this.idle = resolve))
        console.log("2) faol so'rovlar tugadi")
    }
    onApplicationShutdown() { console.log("3) server to'xtadi") }
}

@Injectable()
class CountInterceptor implements NestInterceptor {
    constructor(private readonly inFlight: InFlight) {}
    intercept(_ctx: ExecutionContext, next: CallHandler) {
        this.inFlight.enter()
        return next.handle().pipe(finalize(() => this.inFlight.leave()))
    }
}

@Controller("report")
@UseInterceptors(CountInterceptor)
class ReportController {
    @Get() async build() {
        console.log("  handler: hisobot tayyorlanmoqda...")
        await sleep(80)
        return { ready: true }
    }
}

@Module({ controllers: [ReportController], providers: [InFlight, CountInterceptor] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const slow = http.get("/report")   // kutmaymiz: so'rov "havoda"
    await sleep(20)
    await http.close()                 // yopilish so'rov tugashini kutadi
    await slow
}
main()

