import { Injectable, Module, OnModuleDestroy } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

@Injectable() class BufferedLogger implements OnModuleDestroy {
    private buffer: string[] = []
    log(msg: string) { this.buffer.push(msg); if (this.buffer.length >= 3) this.flush("bufer to'ldi") }
    private flush(reason: string) {
        if (!this.buffer.length) return
        console.log(`[flush: ${reason}] ${this.buffer.join(" | ")}`)
        this.buffer = []
    }
    onModuleDestroy() { this.flush("yopilish") }
}
@Module({ providers: [BufferedLogger] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const log = app.get(BufferedLogger)
    for (const m of ["kirish", "buyurtma", "to'lov", "chiqish"]) log.log(m)
    console.log("close() chaqirilmoqda...")
    await app.close()
}
main()

