import { Injectable, Module, OnModuleDestroy } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

type Ctor<T = object> = new (...args: any[]) => T
function WithDisposable<TBase extends Ctor>(Base: TBase) {
    return class extends Base implements OnModuleDestroy {
        resources: string[] = []
        track(r: string) { this.resources.push(r) }
        onModuleDestroy() { console.log(`${this.constructor.name}: yopildi → ${this.resources.join(", ")}`) }
    }
}
class FileServiceBase { read(name: string) { return `${name} o'qildi` } }
@Injectable() class FileService extends WithDisposable(FileServiceBase) {
    open(name: string) { this.track(name); return this.read(name) }
}
@Module({ providers: [FileService] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const files = app.get(FileService)
    console.log(files.open("a.txt"))
    console.log(files.open("b.csv"))
    await app.close()
}
main()

