import { BeforeApplicationShutdown, Injectable, Module, OnApplicationBootstrap } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms))
@Injectable() class Worker implements OnApplicationBootstrap, BeforeApplicationShutdown {
    private queue = ["email-1", "email-2", "email-3", "email-4", "email-5"]
    private running = false
    private loop?: Promise<void>
    done: string[] = []
    onProgress?: (n: number) => void
    onApplicationBootstrap() { this.running = true; this.loop = this.run() }
    private async run() {
        while (this.running && this.queue.length) {
            const job = this.queue.shift()!
            await sleep(10)
            this.done.push(job)
            this.onProgress?.(this.done.length)
        }
    }
    async beforeApplicationShutdown() {
        this.running = false
        await this.loop
        console.log(`To'xtadi. Bajarildi: ${this.done.join(", ")} | navbatda qoldi: ${this.queue.length}`)
    }
}
@Module({ providers: [Worker] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const worker = app.get(Worker)
    await new Promise<void>(resolve => { worker.onProgress = n => { if (n === 2) resolve() } })
    console.log("2 ta ish bajarildi — yopamiz")
    await app.close()
}
main()

