    const moduleRef = await Test.createTestingModule({ providers: [Pool] }).compile()
    await moduleRef.init()
    console.log(`${name}: ochiq pool = ${openPools}`)
    if (close) await moduleRef.close()   // afterEach(() => moduleRef.close())
}

