import { CanActivate, Controller, Delete, ExecutionContext, ForbiddenException, Get, Injectable, Module, RequestMethod, UseGuards } from "@nestjs/common"

const ACL: Record<string, string[]> = {
    "GET /orders": ["user", "admin"],
    "GET /orders/:id": ["user", "admin"],
    "DELETE /orders/:id": ["admin"],
}
@Injectable() class AclGuard implements CanActivate {
    canActivate(ctx: ExecutionContext) {
        const h = ctx.getHandler()
        const path = Reflect.getMetadata("path", h)
        const key = `${RequestMethod[Reflect.getMetadata("method", h)]} /${Reflect.getMetadata("path", ctx.getClass())}${path === "/" ? "" : "/" + path}`
        const role = ctx.switchToHttp().getRequest().headers["x-role"] ?? "guest"
        if (!(ACL[key] ?? []).includes(role)) throw new ForbiddenException(`${role} uchun ${key} yopiq`)
        return true
    }
}
