import { CanActivate, Controller, ExecutionContext, Get, Injectable, Module } from "@nestjs/common"
import { APP_GUARD } from "@nestjs/core"
import { ExecutionContextHost } from "@nestjs/core/helpers/execution-context-host"

@Injectable()
class ApiKeyGuard implements CanActivate {
    canActivate(ctx: ExecutionContext) {
        if (ctx.getType() !== "http") return true   // RPC va WS xabarlariga tegmaymiz
        return ctx.switchToHttp().getRequest().headers["x-api-key"] === "maxfiy"
    }
}

@Controller("ping")
class PingController {
    @Get() ping() { return "pong" }
}

@Module({ controllers: [PingController], providers: [{ provide: APP_GUARD, useClass: ApiKeyGuard }] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/ping")
    await http.get("/ping", { "x-api-key": "maxfiy" })

    // Haqiqiy mikroservis/gateway o'rniga kontekstlarni qo'lda yasaymiz: [data, context] va [client, data, pattern]
    const guard = new ApiKeyGuard()
    const rpc = new ExecutionContextHost([{ n: 1 }, { pattern: "sum" }], PingController, PingController.prototype.ping)
    rpc.setType("rpc")
    const ws = new ExecutionContextHost([{ id: "socket-1" }, "salom", "chat"], PingController, PingController.prototype.ping)
    ws.setType("ws")
    console.log(`rpc → ruxsat: ${guard.canActivate(rpc)}, data: ${JSON.stringify(rpc.switchToRpc().getData())}`)
    console.log(`ws → ruxsat: ${guard.canActivate(ws)}, data: ${ws.switchToWs().getData()}, pattern: ${ws.switchToWs().getPattern()}`)
    await http.close()
}
main()

