interface Plugin { name: string; apply(text: string): string }
@Injectable() class Trim implements Plugin { name = "trim"; apply(t: string) { return t.trim() } }
@Injectable() class Upper implements Plugin { name = "upper"; apply(t: string) { return t.toUpperCase() } }
@Injectable() class Exclaim implements Plugin { name = "exclaim"; apply(t: string) { return t + "!" } }

const PLUGINS = { trim: Trim, upper: Upper, exclaim: Exclaim }

@Injectable()
class Pipeline {
    constructor(private readonly moduleRef: ModuleRef) {}
    run(text: string, steps: (keyof typeof PLUGINS)[]) {
        return steps.reduce((acc, s) => this.moduleRef.get<Plugin>(PLUGINS[s]).apply(acc), text)
    }
}

@Module({ providers: [Trim, Upper, Exclaim, Pipeline] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const p = app.get(Pipeline)
    console.log(p.run("  salom dunyo  ", ["trim", "upper"]))
    console.log(p.run("  salom dunyo  ", ["trim", "exclaim"]))
    await app.close()
}
