import { Injectable, Module, Type } from "@nestjs/common"
import { ModuleRef, NestFactory } from "@nestjs/core"

class CreateUser { constructor(public name: string) {} }
class DeleteUser { constructor(public id: number) {} }
class BanUser { constructor(public id: number) {} }
type Handler = { execute(cmd: object): string }
@Injectable() class CreateUserHandler implements Handler { execute(c: CreateUser) { return `yaratildi: ${c.name}` } }
@Injectable() class DeleteUserHandler implements Handler { execute(c: DeleteUser) { return `o'chirildi: #${c.id}` } }
const HANDLERS = new Map<Function, Type<Handler>>([[CreateUser, CreateUserHandler], [DeleteUser, DeleteUserHandler]])
@Injectable() class CommandBus {
    constructor(private ref: ModuleRef) {}
    execute(cmd: object) {
        const H = HANDLERS.get(cmd.constructor)
        if (!H) throw new Error(`Handler yo'q: ${cmd.constructor.name}`)
        return this.ref.get(H).execute(cmd)
    }
}
@Module({ providers: [CommandBus, CreateUserHandler, DeleteUserHandler] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const bus = app.get(CommandBus)
    console.log(bus.execute(new CreateUser("Zarina")))
    console.log(bus.execute(new DeleteUser(7)))
    try { bus.execute(new BanUser(3)) } catch (e) { console.log((e as Error).message) }
    await app.close()
}
main()

