type AppReq = { headers: Record<string, string>; ctxId?: ContextId; ru?: RequestUser }
@Injectable({ scope: Scope.REQUEST }) class RequestUser {
    constructor(@Inject(REQUEST) private req: AppReq) {}
    get name() { return this.req.headers["x-user"] ?? "mehmon" }
