@Injectable() class UserGuard implements CanActivate {
    constructor(private ref: ModuleRef) {}
    async canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest<AppReq>()
        req.ctxId = ContextIdFactory.create()
        this.ref.registerRequestByContextId(req, req.ctxId)
        req.ru = await this.ref.resolve(RequestUser, req.ctxId)
        return true
    }
}
