    constructor(private ref: ModuleRef) {}
    @Get() async hi(@Req() req: AppReq) {
        const again = await this.ref.resolve(RequestUser, req.ctxId)
        return { salom: again.name, birXilNusxa: again === req.ru }
    }
}
@Module({ controllers: [H], providers: [RequestUser, UserGuard] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/hello", { "X-User": "Dilnoza" })
