type Indicator = { name: string; check(): Promise<boolean> }
@Injectable() class DbHealth implements Indicator { name = "database"; async check() { return true } }
@Injectable() class RedisHealth implements Indicator { name = "redis"; async check() { return false } }
@Injectable() class DiskHealth implements Indicator { name = "disk"; async check() { return true } }
