function findCycle(graph: Record<string, string[]>): string[] | null {
    const state = new Map<string, "visiting" | "done">()
    const stack: string[] = []
    function dfs(node: string): string[] | null {
        state.set(node, "visiting")
        stack.push(node)
        for (const next of graph[node] ?? []) {
            if (state.get(next) === "visiting") return [...stack.slice(stack.indexOf(next)), next]
            if (!state.has(next)) { const c = dfs(next); if (c) return c }
        }
        stack.pop()
        state.set(node, "done")
        return null
    }
    for (const n of Object.keys(graph)) if (!state.has(n)) { const c = dfs(n); if (c) return c }
    return null
}

