const deps: Record<string, string[]> = {
    AppService: ["UsersService", "Logger"],
    UsersService: ["Database", "Logger"],
    Database: ["Config"],
    Logger: ["Config"],
    Config: [],
}

const waiting = new Map(Object.entries(deps).map(([k, v]) => [k, v.length]))
const queue = [...waiting].filter(([, n]) => n === 0).map(([k]) => k)
const order: string[] = []
while (queue.length) {
    const done = queue.shift()!
    order.push(done)
    for (const [name, list] of Object.entries(deps)) {
        if (!list.includes(done)) continue
        waiting.set(name, waiting.get(name)! - 1)
        if (waiting.get(name) === 0) queue.push(name)
    }
}
console.log(order.join(" → "))
console.log(order.length === Object.keys(deps).length ? "Sikl yo'q" : "Sikl bor!")

