function safeStringify(value: unknown) {
    const seen = new WeakSet<object>()
    return JSON.stringify(value, (_key, v) => {
        if (v && typeof v === "object") {
            if (seen.has(v)) return "[Circular]"
            seen.add(v)
        }
        return v
    })
}

