import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

type Gateway = { pay(amount: number): string }
@Injectable() class PaymentRegistry {
    private items = new Map<string, Gateway>()
    add(name: string, g: Gateway) { this.items.set(name, g) }
    get(name: string) { const g = this.items.get(name); if (!g) throw new Error(`${name} topilmadi`); return g }
    names() { return [...this.items.keys()] }
}
@Injectable() class ClickGateway implements Gateway {
    constructor(r: PaymentRegistry) { r.add("click", this) }
    pay(a: number) { return `Click ${a}` }
}
@Injectable() class UzumGateway implements Gateway {
    constructor(r: PaymentRegistry) { r.add("uzum", this) }
    pay(a: number) { return `Uzum ${a}` }
}
@Injectable() class CheckoutService {
    constructor(private registry: PaymentRegistry) {}
    pay(method: string, amount: number) { return this.registry.get(method).pay(amount) }
}
@Module({ providers: [PaymentRegistry, ClickGateway, UzumGateway, CheckoutService] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const checkout = app.get(CheckoutService)
    console.log("Mavjud:", app.get(PaymentRegistry).names())
    console.log(checkout.pay("uzum", 120000))
    try { checkout.pay("paypal", 1) } catch (e) { console.log("Xato:", (e as Error).message) }
    await app.close()
}
main()

import { forwardRef, Module } from "@nestjs/common"
import { ModulesContainer, NestFactory } from "@nestjs/core"

@Module({ imports: [forwardRef(() => UsersModule)] }) class AuthModule {}
@Module({ imports: [forwardRef(() => AuthModule)] }) class UsersModule {}
@Module({ imports: [AuthModule] }) class AppModule {}

function findCycle(container: ModulesContainer): string[] | null {
    const visiting: string[] = []
    const done = new Set<string>()
    const visit = (module: { name: string; imports: Set<{ name: string; imports: Set<any> }> }): string[] | null => {
        const at = visiting.indexOf(module.name)
        if (at >= 0) return [...visiting.slice(at), module.name]
        if (done.has(module.name)) return null
        visiting.push(module.name)
        for (const next of module.imports) {
            const cycle = visit(next)
            if (cycle) return cycle
        }
        visiting.pop()
        done.add(module.name)
        return null
    }
    for (const module of container.values()) {
        if (module.name === "InternalCoreModule") continue
        const cycle = visit(module)
        if (cycle) return cycle
    }
    return null
}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const cycle = findCycle(app.get(ModulesContainer))
    console.log(cycle ? `Sikl: ${cycle.join(" → ")}` : "Sikl yo'q")
    await app.close()
}
main()
